//Climatizador inverter es hija de Climatizador. No implementa ninguna interfaz nueva
public class ClimatizadorInverter extends Climatizador {

    // Constructor vacio
    public ClimatizadorInverter() {
        super();
    }


    // Constructor completo
    public ClimatizadorInverter(String codigo, Oficina oficina, double potenciaNominal) {
        super(codigo, oficina, potenciaNominal);
    }


    // Ajustar nivel (ahora entre 10 y 100)
    @Override
    public boolean ajustarNivel(int nivel) {

        if (!encendido) {
            return false;
        }

        if (nivel < 10 || nivel > 100) {
            return false;
        }

        this.nivel = nivel;
        return true;
    }


    // Calcular consumo por hora - 20%
    @Override
    public double calcularConsumoHora() {
        return super.calcularConsumoHora() * 0.80;
    }


    // toString
    // Reutiliza los datos de Climatizador
    // e identifica que es un dispositivo inverter

    @Override
    public String toString() {
        return super.toString() + "\nTipo: Climatizador Inverter";
    }
}

